mkitem!{# [doc = " Reinterprets the bits of a value of one type as another type."] # [doc = ""] # [doc = " Both types must have the same size. Compilation will fail if this is not guaranteed."] # [doc = ""] # [doc = " `transmute` is semantically equivalent to a bitwise move of one type"] # [doc = " into another. It copies the bits from the source value into the"] # [doc = " destination value, then forgets the original. Note that source and destination"] # [doc = " are passed by-value, which means if `Src` or `Dst` contain padding, that padding"] # [doc = " is *not* guaranteed to be preserved by `transmute`."] # [doc = ""] # [doc = " Both the argument and the result must be [valid](../../nomicon/what-unsafe-does.html) at"] # [doc = " their given type. Violating this condition leads to [undefined behavior][ub]. The compiler"] # [doc = " will generate code *assuming that you, the programmer, ensure that there will never be"] # [doc = " undefined behavior*. It is therefore your responsibility to guarantee that every value"] # [doc = " passed to `transmute` is valid at both types `Src` and `Dst`. Failing to uphold this condition"] # [doc = " may lead to unexpected and unstable compilation results. This makes `transmute` **incredibly"] # [doc = " unsafe**. `transmute` should be the absolute last resort."] # [doc = ""] # [doc = " Because `transmute` is a by-value operation, alignment of the *transmuted values"] # [doc = " themselves* is not a concern. As with any other function, the compiler already ensures"] # [doc = " both `Src` and `Dst` are properly aligned. However, when transmuting values that *point"] # [doc = " elsewhere* (such as pointers, references, boxes…), the caller has to ensure proper"] # [doc = " alignment of the pointed-to values."] # [doc = ""] # [doc = " The [nomicon](../../nomicon/transmutes.html) has additional documentation."] # [doc = ""] # [doc = " [ub]: ../../reference/behavior-considered-undefined.html"] # [doc = ""] # [doc = " # Transmutation between pointers and integers"] # [doc = ""] # [doc = " Special care has to be taken when transmuting between pointers and integers, e.g."] # [doc = " transmuting between `*const ()` and `usize`."] # [doc = ""] # [doc = " Transmuting *pointers to integers* in a `const` context is [undefined behavior][ub], unless"] # [doc = " the pointer was originally created *from* an integer. (That includes this function"] # [doc = " specifically, integer-to-pointer casts, and helpers like [`dangling`][crate::ptr::dangling],"] # [doc = " but also semantically-equivalent conversions such as punning through `repr(C)` union"] # [doc = " fields.) Any attempt to use the resulting value for integer operations will abort"] # [doc = " const-evaluation. (And even outside `const`, such transmutation is touching on many"] # [doc = " unspecified aspects of the Rust memory model and should be avoided. See below for"] # [doc = " alternatives.)"] # [doc = ""] # [doc = " Transmuting *integers to pointers* is a largely unspecified operation. It is likely *not*"] # [doc = " equivalent to an `as` cast. Doing non-zero-sized memory accesses with a pointer constructed"] # [doc = " this way is currently considered undefined behavior."] # [doc = ""] # [doc = " All this also applies when the integer is nested inside an array, tuple, struct, or enum."] # [doc = " However, `MaybeUninit<usize>` is not considered an integer type for the purpose of this"] # [doc = " section. Transmuting `*const ()` to `MaybeUninit<usize>` is fine---but then calling"] # [doc = " `assume_init()` on that result is considered as completing the pointer-to-integer transmute"] # [doc = " and thus runs into the issues discussed above."] # [doc = ""] # [doc = " In particular, doing a pointer-to-integer-to-pointer roundtrip via `transmute` is *not* a"] # [doc = " lossless process. If you want to round-trip a pointer through an integer in a way that you"] # [doc = " can get back the original pointer, you need to use `as` casts, or replace the integer type"] # [doc = " by `MaybeUninit<$int>` (and never call `assume_init()`). If you are looking for a way to"] # [doc = " store data of arbitrary type, also use `MaybeUninit<T>` (that will also handle uninitialized"] # [doc = " memory due to padding). If you specifically need to store something that is \"either an"] # [doc = " integer or a pointer\", use `*mut ()`: integers can be converted to pointers and back without"] # [doc = " any loss (via `as` casts or via `transmute`)."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " There are a few things that `transmute` is really useful for."] # [doc = ""] # [doc = " Turning a pointer into a function pointer. This is *not* portable to"] # [doc = " machines where function pointers and data pointers have different sizes."] # [doc = ""] # [doc = " ```"] # [doc = " fn foo() -> i32 {"] # [doc = "     0"] # [doc = " }"] # [doc = " // Crucially, we `as`-cast to a raw pointer before `transmute`ing to a function pointer."] # [doc = " // This avoids an integer-to-pointer `transmute`, which can be problematic."] # [doc = " // Transmuting between raw pointers and function pointers (i.e., two pointer types) is fine."] # [doc = " let pointer = foo as *const ();"] # [doc = " let function = unsafe {"] # [doc = "     std::mem::transmute::<*const (), fn() -> i32>(pointer)"] # [doc = " };"] # [doc = " assert_eq!(function(), 0);"] # [doc = " ```"] # [doc = ""] # [doc = " Extending a lifetime, or shortening an invariant lifetime. This is"] # [doc = " advanced, very unsafe Rust!"] # [doc = ""] # [doc = " ```"] # [doc = " struct R<'a>(&'a i32);"] # [doc = " unsafe fn extend_lifetime<'b>(r: R<'b>) -> R<'static> {"] # [doc = "     unsafe { std::mem::transmute::<R<'b>, R<'static>>(r) }"] # [doc = " }"] # [doc = ""] # [doc = " unsafe fn shorten_invariant_lifetime<'b, 'c>(r: &'b mut R<'static>)"] # [doc = "                                              -> &'b mut R<'c> {"] # [doc = "     unsafe { std::mem::transmute::<&'b mut R<'static>, &'b mut R<'c>>(r) }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " # Alternatives"] # [doc = ""] # [doc = " Don't despair: many uses of `transmute` can be achieved through other means."] # [doc = " Below are common applications of `transmute` which can be replaced with safer"] # [doc = " constructs."] # [doc = ""] # [doc = " Turning raw bytes (`[u8; SZ]`) into `u32`, `f64`, etc.:"] # [doc = ""] # [doc = " ```"] # [doc = " # #![allow(unnecessary_transmutes)]"] # [doc = " let raw_bytes = [0x78, 0x56, 0x34, 0x12];"] # [doc = ""] # [doc = " let num = unsafe {"] # [doc = "     std::mem::transmute::<[u8; 4], u32>(raw_bytes)"] # [doc = " };"] # [doc = ""] # [doc = " // use `u32::from_ne_bytes` instead"] # [doc = " let num = u32::from_ne_bytes(raw_bytes);"] # [doc = " // or use `u32::from_le_bytes` or `u32::from_be_bytes` to specify the endianness"] # [doc = " let num = u32::from_le_bytes(raw_bytes);"] # [doc = " assert_eq!(num, 0x12345678);"] # [doc = " let num = u32::from_be_bytes(raw_bytes);"] # [doc = " assert_eq!(num, 0x78563412);"] # [doc = " ```"] # [doc = ""] # [doc = " Turning a pointer into a `usize`:"] # [doc = ""] # [doc = " ```no_run"] # [doc = " let ptr = &0;"] # [doc = " let ptr_num_transmute = unsafe {"] # [doc = "     std::mem::transmute::<&i32, usize>(ptr)"] # [doc = " };"] # [doc = ""] # [doc = " // Use an `as` cast instead"] # [doc = " let ptr_num_cast = ptr as *const i32 as usize;"] # [doc = " ```"] # [doc = ""] # [doc = " Note that using `transmute` to turn a pointer to a `usize` is (as noted above) [undefined"] # [doc = " behavior][ub] in `const` contexts. Also outside of consts, this operation might not behave"] # [doc = " as expected -- this is touching on many unspecified aspects of the Rust memory model."] # [doc = " Depending on what the code is doing, the following alternatives are preferable to"] # [doc = " pointer-to-integer transmutation:"] # [doc = " - If the code just wants to store data of arbitrary type in some buffer and needs to pick a"] # [doc = "   type for that buffer, it can use [`MaybeUninit`][crate::mem::MaybeUninit]."] # [doc = " - If the code actually wants to work on the address the pointer points to, it can use `as`"] # [doc = "   casts or [`ptr.addr()`][pointer::addr]."] # [doc = ""] # [doc = " Turning a `*mut T` into a `&mut T`:"] # [doc = ""] # [doc = " ```"] # [doc = " let ptr: *mut i32 = &mut 0;"] # [doc = " let ref_transmuted = unsafe {"] # [doc = "     std::mem::transmute::<*mut i32, &mut i32>(ptr)"] # [doc = " };"] # [doc = ""] # [doc = " // Use a reborrow instead"] # [doc = " let ref_casted = unsafe { &mut *ptr };"] # [doc = " ```"] # [doc = ""] # [doc = " Turning a `&mut T` into a `&mut U`:"] # [doc = ""] # [doc = " ```"] # [doc = " let ptr = &mut 0;"] # [doc = " let val_transmuted = unsafe {"] # [doc = "     std::mem::transmute::<&mut i32, &mut u32>(ptr)"] # [doc = " };"] # [doc = ""] # [doc = " // Now, put together `as` and reborrowing - note the chaining of `as`"] # [doc = " // `as` is not transitive"] # [doc = " let val_casts = unsafe { &mut *(ptr as *mut i32 as *mut u32) };"] # [doc = " ```"] # [doc = ""] # [doc = " Turning a `&str` into a `&[u8]`:"] # [doc = ""] # [doc = " ```"] # [doc = " // this is not a good way to do this."] # [doc = " let slice = unsafe { std::mem::transmute::<&str, &[u8]>(\"Rust\") };"] # [doc = " assert_eq!(slice, &[82, 117, 115, 116]);"] # [doc = ""] # [doc = " // You could use `str::as_bytes`"] # [doc = " let slice = \"Rust\".as_bytes();"] # [doc = " assert_eq!(slice, &[82, 117, 115, 116]);"] # [doc = ""] # [doc = " // Or, just use a byte string, if you have control over the string"] # [doc = " // literal"] # [doc = " assert_eq!(b\"Rust\", &[82, 117, 115, 116]);"] # [doc = " ```"] # [doc = ""] # [doc = " Turning a `Vec<&T>` into a `Vec<Option<&T>>`."] # [doc = ""] # [doc = " To transmute the inner type of the contents of a container, you must make sure to not"] # [doc = " violate any of the container's invariants. For `Vec`, this means that both the size"] # [doc = " *and alignment* of the inner types have to match. Other containers might rely on the"] # [doc = " size of the type, alignment, or even the `TypeId`, in which case transmuting wouldn't"] # [doc = " be possible at all without violating the container invariants."] # [doc = ""] # [doc = " ```"] # [doc = " let store = [0, 1, 2, 3];"] # [doc = " let v_orig = store.iter().collect::<Vec<&i32>>();"] # [doc = ""] # [doc = " // clone the vector as we will reuse them later"] # [doc = " let v_clone = v_orig.clone();"] # [doc = ""] # [doc = " // Using transmute: this relies on the unspecified data layout of `Vec`, which is a"] # [doc = " // bad idea and could cause Undefined Behavior."] # [doc = " // However, it is no-copy."] # [doc = " let v_transmuted = unsafe {"] # [doc = "     std::mem::transmute::<Vec<&i32>, Vec<Option<&i32>>>(v_clone)"] # [doc = " };"] # [doc = ""] # [doc = " let v_clone = v_orig.clone();"] # [doc = ""] # [doc = " // This is the suggested, safe way."] # [doc = " // It may copy the entire vector into a new one though, but also may not."] # [doc = " let v_collected = v_clone.into_iter()"] # [doc = "                          .map(Some)"] # [doc = "                          .collect::<Vec<Option<&i32>>>();"] # [doc = ""] # [doc = " let v_clone = v_orig.clone();"] # [doc = ""] # [doc = " // This is the proper no-copy, unsafe way of \"transmuting\" a `Vec`, without relying on the"] # [doc = " // data layout. Instead of literally calling `transmute`, we perform a pointer cast, but"] # [doc = " // in terms of converting the original inner type (`&i32`) to the new one (`Option<&i32>`),"] # [doc = " // this has all the same caveats. Besides the information provided above, also consult the"] # [doc = " // [`from_raw_parts`] documentation."] # [doc = " let v_from_raw = unsafe {"] # [doc = "     // Ensure the original vector is not dropped."] # [doc = "     let mut v_clone = std::mem::ManuallyDrop::new(v_clone);"] # [doc = "     Vec::from_raw_parts(v_clone.as_mut_ptr() as *mut Option<&i32>,"] # [doc = "                         v_clone.len(),"] # [doc = "                         v_clone.capacity())"] # [doc = " };"] # [doc = " ```"] # [doc = ""] # [doc = " [`from_raw_parts`]: ../../std/vec/struct.Vec.html#method.from_raw_parts"] # [doc = ""] # [doc = " Implementing `split_at_mut`:"] # [doc = ""] # [doc = " ```"] # [doc = " use std::{slice, mem};"] # [doc = ""] # [doc = " // There are multiple ways to do this, and there are multiple problems"] # [doc = " // with the following (transmute) way."] # [doc = " fn split_at_mut_transmute<T>(slice: &mut [T], mid: usize)"] # [doc = "                              -> (&mut [T], &mut [T]) {"] # [doc = "     let len = slice.len();"] # [doc = "     assert!(mid <= len);"] # [doc = "     unsafe {"] # [doc = "         let slice2 = mem::transmute::<&mut [T], &mut [T]>(slice);"] # [doc = "         // first: transmute is not type safe; all it checks is that T and"] # [doc = "         // U are of the same size. Second, right here, you have two"] # [doc = "         // mutable references pointing to the same memory."] # [doc = "         (&mut slice[0..mid], &mut slice2[mid..len])"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " // This gets rid of the type safety problems; `&mut *` will *only* give"] # [doc = " // you a `&mut T` from a `&mut T` or `*mut T`."] # [doc = " fn split_at_mut_casts<T>(slice: &mut [T], mid: usize)"] # [doc = "                          -> (&mut [T], &mut [T]) {"] # [doc = "     let len = slice.len();"] # [doc = "     assert!(mid <= len);"] # [doc = "     unsafe {"] # [doc = "         let slice2 = &mut *(slice as *mut [T]);"] # [doc = "         // however, you still have two mutable references pointing to"] # [doc = "         // the same memory."] # [doc = "         (&mut slice[0..mid], &mut slice2[mid..len])"] # [doc = "     }"] # [doc = " }"] # [doc = ""] # [doc = " // This is how the standard library does it. This is the best method, if"] # [doc = " // you need to do something like this"] # [doc = " fn split_at_stdlib<T>(slice: &mut [T], mid: usize)"] # [doc = "                       -> (&mut [T], &mut [T]) {"] # [doc = "     let len = slice.len();"] # [doc = "     assert!(mid <= len);"] # [doc = "     unsafe {"] # [doc = "         let ptr = slice.as_mut_ptr();"] # [doc = "         // This now has three mutable references pointing at the same"] # [doc = "         // memory. `slice`, the rvalue ret.0, and the rvalue ret.1."] # [doc = "         // `slice` is never used after `let ptr = ...`, and so one can"] # [doc = "         // treat it as \"dead\", and therefore, you only have two real"] # [doc = "         // mutable slices."] # [doc = "         (slice::from_raw_parts_mut(ptr, mid),"] # [doc = "          slice::from_raw_parts_mut(ptr.add(mid), len - mid))"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] # [rustc_allowed_through_unstable_modules = "import this function via `std::mem` instead"] # [rustc_const_stable (feature = "const_transmute" , since = "1.56.0")] # [rustc_diagnostic_item = "transmute"] # [rustc_nounwind] # [rustc_intrinsic] pub const unsafe fn transmute < Src , Dst > (src : Src) -> Dst ;}
mkitem!{# [doc = " Like [`transmute`], but even less checked at compile-time: rather than"] # [doc = " giving an error for `size_of::<Src>() != size_of::<Dst>()`, it's"] # [doc = " **Undefined Behavior** at runtime."] # [doc = ""] # [doc = " Prefer normal `transmute` where possible, for the extra checking, since"] # [doc = " both do exactly the same thing at runtime, if they both compile."] # [doc = ""] # [doc = " This is not expected to ever be exposed directly to users, rather it"] # [doc = " may eventually be exposed through some more-constrained API."] # [rustc_intrinsic_const_stable_indirect] # [rustc_nounwind] # [rustc_intrinsic] pub const unsafe fn transmute_unchecked < Src , Dst > (src : Src) -> Dst ;}
mkitem!{# [doc = " Returns `true` if the actual type given as `T` requires drop"] # [doc = " glue; returns `false` if the actual type provided for `T`"] # [doc = " implements `Copy`."] # [doc = ""] # [doc = " If the actual type neither requires drop glue nor implements"] # [doc = " `Copy`, then the return value of this function is unspecified."] # [doc = ""] # [doc = " Note that, unlike most intrinsics, this can only be called at compile-time"] # [doc = " as backends do not have an implementation for it. The only caller (its"] # [doc = " stable counterpart) wraps this intrinsic call in a `const` block so that"] # [doc = " backends only see an evaluated constant."] # [doc = ""] # [doc = " The stabilized version of this intrinsic is [`mem::needs_drop`](crate::mem::needs_drop)."] # [rustc_intrinsic_const_stable_indirect] # [rustc_nounwind] # [rustc_intrinsic] pub const fn needs_drop < T : ? Sized > () -> bool ;}
mkitem!{# [doc = " Calculates the offset from a pointer."] # [doc = ""] # [doc = " This is implemented as an intrinsic to avoid converting to and from an"] # [doc = " integer, since the conversion would throw away aliasing information."] # [doc = ""] # [doc = " This can only be used with `Ptr` as a raw pointer type (`*mut` or `*const`)"] # [doc = " to a `Sized` pointee and with `Delta` as `usize` or `isize`.  Any other"] # [doc = " instantiations may arbitrarily misbehave, and that's *not* a compiler bug."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " If the computed offset is non-zero, then both the starting and resulting pointer must be"] # [doc = " either in bounds or at the end of an allocation. If either pointer is out"] # [doc = " of bounds or arithmetic overflow occurs then this operation is undefined behavior."] # [doc = ""] # [doc = " The stabilized version of this intrinsic is [`pointer::offset`]."] # [must_use = "returns a new pointer rather than modifying its argument"] # [rustc_intrinsic_const_stable_indirect] # [rustc_nounwind] # [rustc_intrinsic] pub const unsafe fn offset < Ptr : bounds :: BuiltinDeref , Delta > (dst : Ptr , offset : Delta) -> Ptr ;}
mkitem!{# [doc = " Calculates the offset from a pointer, potentially wrapping."] # [doc = ""] # [doc = " This is implemented as an intrinsic to avoid converting to and from an"] # [doc = " integer, since the conversion inhibits certain optimizations."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " Unlike the `offset` intrinsic, this intrinsic does not restrict the"] # [doc = " resulting pointer to point into or at the end of an allocated"] # [doc = " object, and it wraps with two's complement arithmetic. The resulting"] # [doc = " value is not necessarily valid to be used to actually access memory."] # [doc = ""] # [doc = " The stabilized version of this intrinsic is [`pointer::wrapping_offset`]."] # [must_use = "returns a new pointer rather than modifying its argument"] # [rustc_intrinsic_const_stable_indirect] # [rustc_nounwind] # [rustc_intrinsic] pub const unsafe fn arith_offset < T > (dst : * const T , offset : isize) -> * const T ;}
mkitem!{# [doc = " Projects to the `index`-th element of `slice_ptr`, as the same kind of pointer"] # [doc = " as the slice was provided -- so `&mut [T] → &mut T`, `&[T] → &T`,"] # [doc = " `*mut [T] → *mut T`, or `*const [T] → *const T` -- without a bounds check."] # [doc = ""] # [doc = " This is exposed via `<usize as SliceIndex>::get(_unchecked)(_mut)`,"] # [doc = " and isn't intended to be used elsewhere."] # [doc = ""] # [doc = " Expands in MIR to `{&, &mut, &raw const, &raw mut} (*slice_ptr)[index]`,"] # [doc = " depending on the types involved, so no backend support is needed."] # [doc = ""] # [doc = " # Safety"] # [doc = ""] # [doc = " - `index < PtrMetadata(slice_ptr)`, so the indexing is in-bounds for the slice"] # [doc = " - the resulting offsetting is in-bounds of the allocation, which is"] # [doc = "   always the case for references, but needs to be upheld manually for pointers"] # [rustc_nounwind] # [rustc_intrinsic] pub const unsafe fn slice_get_unchecked < ItemPtr : bounds :: ChangePointee < [T] , Pointee = T , Output = SlicePtr >, SlicePtr , T , > (slice_ptr : SlicePtr , index : usize ,) -> ItemPtr ;}
mkitem!{# [doc = " Masks out bits of the pointer according to a mask."] # [doc = ""] # [doc = " Note that, unlike most intrinsics, this is safe to call;"] # [doc = " it does not require an `unsafe` block."] # [doc = " Therefore, implementations must not require the user to uphold"] # [doc = " any safety invariants."] # [doc = ""] # [doc = " Consider using [`pointer::mask`] instead."] # [rustc_nounwind] # [rustc_intrinsic] pub fn ptr_mask < T > (ptr : * const T , mask : usize) -> * const T ;}
mkitem!{# [doc = " Equivalent to the appropriate `llvm.memcpy.p0i8.0i8.*` intrinsic, with"] # [doc = " a size of `count` * `size_of::<T>()` and an alignment of `align_of::<T>()`."] # [doc = ""] # [doc = " This intrinsic does not have a stable counterpart."] # [doc = " # Safety"] # [doc = ""] # [doc = " The safety requirements are consistent with [`copy_nonoverlapping`]"] # [doc = " while the read and write behaviors are volatile,"] # [doc = " which means it will not be optimized out unless `_count` or `size_of::<T>()` is equal to zero."] # [doc = ""] # [doc = " [`copy_nonoverlapping`]: ptr::copy_nonoverlapping"] # [rustc_intrinsic] # [rustc_nounwind] pub unsafe fn volatile_copy_nonoverlapping_memory < T > (dst : * mut T , src : * const T , count : usize) ;}
mkitem!{# [doc = " Equivalent to the appropriate `llvm.memmove.p0i8.0i8.*` intrinsic, with"] # [doc = " a size of `count * size_of::<T>()` and an alignment of `align_of::<T>()`."] # [doc = ""] # [doc = " The volatile parameter is set to `true`, so it will not be optimized out"] # [doc = " unless size is equal to zero."] # [doc = ""] # [doc = " This intrinsic does not have a stable counterpart."] # [rustc_intrinsic] # [rustc_nounwind] pub unsafe fn volatile_copy_memory < T > (dst : * mut T , src : * const T , count : usize) ;}
mkitem!{# [doc = " Equivalent to the appropriate `llvm.memset.p0i8.*` intrinsic, with a"] # [doc = " size of `count * size_of::<T>()` and an alignment of `align_of::<T>()`."] # [doc = ""] # [doc = " This intrinsic does not have a stable counterpart."] # [doc = " # Safety"] # [doc = ""] # [doc = " The safety requirements are consistent with [`write_bytes`] while the write behavior is volatile,"] # [doc = " which means it will not be optimized out unless `_count` or `size_of::<T>()` is equal to zero."] # [doc = ""] # [doc = " [`write_bytes`]: ptr::write_bytes"] # [rustc_intrinsic] # [rustc_nounwind] pub unsafe fn volatile_set_memory < T > (dst : * mut T , val : u8 , count : usize) ;}
