mkitem!{# [doc = " Generates the LLVM body for the automatic differentiation of `f` using Enzyme,"] # [doc = " with `df` as the derivative function and `args` as its arguments."] # [doc = ""] # [doc = " Used internally as the body of `df` when expanding the `#[autodiff_forward]`"] # [doc = " and `#[autodiff_reverse]` attribute macros."] # [doc = ""] # [doc = " Type Parameters:"] # [doc = " - `F`: The original function to differentiate. Must be a function item."] # [doc = " - `G`: The derivative function. Must be a function item."] # [doc = " - `T`: A tuple of arguments passed to `df`."] # [doc = " - `R`: The return type of the derivative function."] # [doc = ""] # [doc = " This shows where the `autodiff` intrinsic is used during macro expansion:"] # [doc = ""] # [doc = " ```rust,ignore (macro example)"] # [doc = " #[autodiff_forward(df1, Dual, Const, Dual)]"] # [doc = " pub fn f1(x: &[f64], y: f64) -> f64 {"] # [doc = "     unimplemented!()"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " expands to:"] # [doc = ""] # [doc = " ```rust,ignore (macro example)"] # [doc = " #[rustc_autodiff]"] # [doc = " #[inline(never)]"] # [doc = " pub fn f1(x: &[f64], y: f64) -> f64 {"] # [doc = "     ::core::panicking::panic(\"not implemented\")"] # [doc = " }"] # [doc = " #[rustc_autodiff(Forward, 1, Dual, Const, Dual)]"] # [doc = " pub fn df1(x: &[f64], bx_0: &[f64], y: f64) -> (f64, f64) {"] # [doc = "     ::core::intrinsics::autodiff(f1::<>, df1::<>, (x, bx_0, y))"] # [doc = " }"] # [doc = " ```"] # [rustc_nounwind] # [rustc_intrinsic] pub const fn autodiff < F , G , T : crate :: marker :: Tuple , R > (f : F , df : G , args : T) -> R ;}

